+    pub worker_id: String,
+    pub url: String,
+    pub role: WorkerMode,
+    pub draining: bool,
+    pub active_load: usize,
+    pub bootstrap_port: Option<u16>,
+}
+
+#[derive(Debug, Serialize, Deserialize)]
+pub struct RouterWorkerControlResponse {
+    pub success: bool,
+    pub message: String,
+    pub worker: Option<RouterWorkerStatus>,
+}
